'use strict';
function personalWater(x,y){if(x<0||y<0||x>=N||y>=N||!navalWalkable(x,y))return false;const b=foreignBuilding(x,y);return !b||!['foreign_keep','foreign_tower','palisada','brama'].includes(b.type)}
function playerMovementBlocked(x,y){return state.playerBoat?.aboard?!personalWater(Math.floor(x/T),Math.floor(y/T)):blocked(x,y)}
function nearbyBoatWater(){const px=Math.floor(state.p.x/T),py=Math.floor(state.p.y/T),spots=[];for(let dx=-2;dx<=2;dx++)for(let dy=-2;dy<=2;dy++){const x=px+dx,y=py+dy,d=Math.hypot((x+.5)*T-state.p.x,(y+.5)*T-state.p.y);if(d<=1.8*T&&personalWater(x,y))spots.push({x:(x+.5)*T,y:(y+.5)*T,d})}return spots.sort((a,b)=>a.d-b.d)[0]}
function buildPersonalBoat(){if(state.playerBoat){say('Masz już łódkę. Wróć do miejsca, w którym ją zostawiłeś.');return false}if(state.wood<20){say('Łódka kosztuje 20 drewna.');return false}const spot=nearbyBoatWater();if(!spot){say('Podejdź do brzegu rzeki, aby zwodować łódkę.');return false}state.wood-=20;state.playerBoat={x:spot.x,y:spot.y,aboard:false,angle:0};save();ui();say('Łódka gotowa! Kliknij „Wsiądź do łódki” lub naciśnij V.');return true}
function boardPersonalBoat(){const b=state.playerBoat;if(!b||b.aboard)return false;if(Math.hypot(b.x-state.p.x,b.y-state.p.y)>1.8*T){say('Podejdź do swojej łódki.');return false}if(!personalWater(Math.floor(b.x/T),Math.floor(b.y/T))){say('Łódkę blokuje budowla. Otwórz bramę lub usuń przeszkodę.');return false}state.p.x=b.x;state.p.y=b.y;b.aboard=true;if(state.life)state.life.mounted=false;target=null;setMode(null);cancelCommand();save();ui();say('Płyniesz! WASD / strzałki lub kliknięcie wody. V — wysiądź przy brzegu.');return true}
function boatLanding(){const px=Math.floor(state.p.x/T),py=Math.floor(state.p.y/T),spots=[];for(let dx=-2;dx<=2;dx++)for(let dy=-2;dy<=2;dy++){const x=px+dx,y=py+dy,cx=(x+.5)*T,cy=(y+.5)*T,b=building(x,y),d=Math.hypot(cx-state.p.x,cy-state.p.y);if(d<=1.8*T&&(terrain(x,y)!=='water'||b?.type==='pomost')&&!blocked(cx,cy)&&!natural(x,y)&&!foreignBuilding(x,y)&&(!b||['sciezka','port','most','most_staly','pomost'].includes(b.type)))spots.push({x:cx,y:cy,d})}return spots.sort((a,b)=>a.d-b.d)[0]}
function leavePersonalBoat(){const b=state.playerBoat;if(!b?.aboard)return false;const spot=boatLanding();if(!spot){say('Podpłyń bliżej pustego brzegu, aby wysiąść.');return false}b.x=state.p.x;b.y=state.p.y;b.aboard=false;state.p.x=spot.x;state.p.y=spot.y;target=null;save();ui();say('Wysiadłeś na brzeg. Łódka czeka na wodzie.');return true}
function togglePersonalBoat(){return state.playerBoat?.aboard?leavePersonalBoat():boardPersonalBoat()}
const boatTravelMultiplier=playerTravelMultiplier;playerTravelMultiplier=function(){return state.playerBoat?.aboard?1.15:boatTravelMultiplier()};
const personalBoatStep=simulationStep;simulationStep=function(dt){const b=state.playerBoat,px=state.p.x,py=state.p.y;personalBoatStep(dt);if(b?.aboard){const dx=state.p.x-px,dy=state.p.y-py;if(Math.hypot(dx,dy)>.01)b.angle=Math.atan2(dy,dx);b.x=state.p.x;b.y=state.p.y}};
function drawPersonalBoat(x,y,aboard=false){const b=state.playerBoat;ctx.save();ctx.translate(x,y+6);ctx.rotate(b?.angle||0);ctx.scale(1+.12*((b?.level||1)-1),1+.16*((b?.level||1)-1));ctx.fillStyle='#c1dbce55';ctx.beginPath();ctx.ellipse(-6,0,27,12,0,0,7);ctx.fill();polygon([[-23,-8],[9,-11],[26,0],[9,11],[-23,8]],'#62482f');polygon([[-19,-5],[9,-8],[21,0],[9,8],[-19,5]],'#b99259');artLine([[-11,-6],[-11,6]],'#765633',3);artLine([[7,-7],[7,7]],'#765633',3);const swing=aboard&&!state.clock?.paused?Math.sin(state.time*6)*5:0;artLine([[-2,-3],[-10+swing,-21]],'#d1b178',2);artLine([[-10+swing,-21],[-14+swing,-26]],'#b48c50',5);artLine([[-2,3],[-10-swing,21]],'#d1b178',2);artLine([[-10-swing,21],[-14-swing,26]],'#b48c50',5);ctx.restore();if(aboard){artRect(x-7,y-10,14,13,'#c7a05f');ctx.fillStyle='#f2d3a1';ctx.beginPath();ctx.arc(x,y-15,6,0,7);ctx.fill();artRect(x-7,y-23,14,5,'#55472f')}}
const personalBoatWorld=drawWarWorld;drawWarWorld=function(){personalBoatWorld();const b=state.playerBoat;if(b&&!b.aboard&&seen.has(tileKey(Math.floor(b.x/T),Math.floor(b.y/T))))drawPersonalBoat(b.x,b.y)};
const boatBuildButton=document.createElement('button');boatBuildButton.textContent='🛶 Zbuduj łódkę · 20 drewna';boatBuildButton.onclick=buildPersonalBoat;$('clockControls').append(boatBuildButton);const boatBoardButton=document.createElement('button');boatBoardButton.textContent='🛶 Wsiądź do łódki · V';boatBoardButton.onclick=togglePersonalBoat;$('clockControls').append(boatBoardButton);
const personalBoatUI=ui;ui=function(){personalBoatUI();const b=state.playerBoat;boatBuildButton.style.display=b?'none':'';boatBoardButton.style.display=b?'':'none';boatBoardButton.textContent=b?.aboard?'🛶 Wysiądź na brzeg · V':'🛶 Wsiądź do łódki · V';boatBoardButton.title=b&&!b.aboard?'Łódka: '+Math.floor(b.x/T)+', '+Math.floor(b.y/T):'Sterowanie: WASD, strzałki lub kliknięcie wody'};
const personalBoatHome=$('home').onclick;$('home').onclick=()=>{const b=state.playerBoat;if(b?.aboard){b.x=state.p.x;b.y=state.p.y;b.aboard=false}personalBoatHome();ui()};
const personalBoatDown=c.onpointerdown;c.onpointerdown=e=>{const b=state.playerBoat,p=worldPoint(e);if(!e.button&&!mode&&b&&!b.aboard&&Math.hypot(p.x-b.x,p.y-b.y)<25){boardPersonalBoat();return}if(!e.button&&b?.aboard&&!mode){target=p;return}personalBoatDown(e)};
window.addEventListener('keydown',e=>{if(e.repeat||['INPUT','TEXTAREA','SELECT'].includes(e.target?.tagName)||e.target?.isContentEditable)return;if(e.key.toLowerCase()==='v'){e.preventDefault();togglePersonalBoat()}});ui();
